insert into public.dev_tracker (key, area, title, detail, status, next_step, sort_order, designed, built, tests_passed, merged, deployed, operational, awaiting) values
  ('social-home', 'Social Ecosystem', 'Home: "Your world. Your connections."', 'One home: My Story, Business, Life, Love and Elite shortcuts; composer (Photo, Video, Event, Thought); Daily Journey card; Connection Feed. Navigation Home, Discover, Connect, Journey, Profile.', 'designed', 'Phase 2, after foundations.', 500, true, false, false, false, false, false, 'owner'),
  ('social-profiles-photos', 'Social Ecosystem', 'Member profiles and photo galleries', 'Profiles with photos (membership limits), per-photo visibility, moderation, location-metadata stripping, storage-level privacy, Elite badge beside names.', 'designed', 'Phase 1. Owner: photo limits per membership.', 501, true, false, false, false, false, false, 'owner'),
  ('social-connections-graph', 'Social Ecosystem', 'Connections graph with intentions', 'Follow (one-way) and connect (mutual) with intention tags: friendship, business, mentorship, travel, hobbies, social, couples friendship, romance (eligible singles only). Never interprets friendship or business as romance.', 'designed', 'Phase 1.', 502, true, false, false, false, false, false, null),
  ('social-conversations', 'Social Ecosystem', 'Conversations: direct, group, couple, event, trip, circle', 'Generalizes the private business inbox into conversations with participants; report, block, leave, mute.', 'designed', 'Phase 1.', 503, true, false, false, false, false, false, null),
  ('social-notifications', 'Social Ecosystem', 'Notification preference center', 'Per type and per circle, quiet hours, in-app and email; all optional. Reuses check-in reminder delivery.', 'designed', 'Phase 1.', 504, true, false, false, false, false, false, null),
  ('social-moderation', 'Social Ecosystem', 'Unified moderation, reporting and appeals', 'One queue for posts, comments, photos, events, circles and messages, with appeals.', 'designed', 'Phase 1.', 505, true, false, false, false, false, false, null),
  ('social-feed', 'Social Ecosystem', 'The Connection Feed', 'Photos, videos, thoughts, accomplishments, life updates, education, event shares; Appreciate, Discuss, Save; audience per post; chronological and circle-based, no outrage ranking; member feed controls. Generalizes the Business Connection Board.', 'designed', 'Phase 2.', 506, true, false, false, false, false, false, null),
  ('social-video', 'Social Ecosystem', 'Short videos and stories', 'Short educational, inspirational and lifestyle videos and stories with moderation and storage limits.', 'designed', 'Later phase; storage cost needs owner approval.', 507, true, false, false, false, false, false, 'owner'),
  ('calendar-events', 'Social Ecosystem', 'The Connect Calendar: create and share events', 'Original or shared events with name, description, flyer, category, date/time/time zone, city/state/country, virtual or in-person, venue, cost, official link, organizer, eligibility, visibility. Labels: organized by a member, shared by a member (external organizer), verified organizer, official. Reuses webinars and registrations.', 'designed', 'Phase 3.', 508, true, false, false, false, false, false, null),
  ('calendar-interactions', 'Social Ecosystem', 'Connect Calendar: member interactions', 'Interested, Attending, Request information, Looking for someone to attend with, invite connections, discussion, private event group conversation, save, share, add to personal or couples calendar, optional reminders, post-event photos and reflections.', 'designed', 'Phase 3.', 509, true, false, false, false, false, false, null),
  ('calendar-discovery', 'Social Ecosystem', 'Connect Calendar: discovery and filters', 'Local, nationwide, international and virtual; filters for location, date, interests, category, price and eligibility; free members discover and share within their experiences; Journey suggestions for paid members.', 'designed', 'Phase 3.', 510, true, false, false, false, false, false, null),
  ('calendar-safety', 'Social Ecosystem', 'Connect Calendar: safety and authenticity', 'Reporting, moderation, organizer verification (identity-verified, owner-approved), fraud signals; no payment collection for member events; attendance and location shown only with consent.', 'designed', 'Phase 3. No paid ticketing without owner approval.', 511, true, false, false, false, false, false, 'owner'),
  ('social-circles', 'Social Ecosystem', 'Find Your Circle: Connection Circles', '20 seeded circles (business, executive leadership, investing and retirement, travel, personal development, conscious living, manifestations, friendships, arts, dining, intentional singles, couples and marriage, life transitions, empty nesters, starting over after divorce, fitness, community involvement, mentorship, Elite, local/national/international). Each has dashboard, directory, feed, discussions, photos, events, activities, group messaging, resources, recommendations, invitations, announcements, notifications, moderation.', 'designed', 'Phase 4.', 512, true, false, false, false, false, false, null),
  ('social-circles-member-created', 'Social Ecosystem', 'Member-created circles with owner approval', 'Eligible members propose circles; owner approval queue; host moderation tools; archive or transfer.', 'designed', 'Phase 4. Owner: who may create circles.', 513, true, false, false, false, false, false, 'owner'),
  ('connection-intelligence', 'Social Ecosystem', 'Connection Intelligence Engine', 'With authorization, uses Art of Self, preferences, interests, values, life stage, goals, travel and relationship intentions to recommend circles, people, events and learning. Members view, correct, pause and delete inputs. Never uses wealth, verification, counseling, health or emotional scores.', 'designed', 'Phase 7.', 514, true, false, false, false, false, false, null),
  ('connection-alignment', 'Social Ecosystem', 'Connection alignment levels with reasons', 'Naturally Aligned, Shared Interests, Growth Connections, Explore Beyond Your Circle, Open Community; every recommendation explains why; members join any eligible community regardless of category.', 'designed', 'Phase 7.', 515, true, false, false, false, false, false, null),
  ('find-people-like-me', 'Social Ecosystem', 'Find People Like Me', 'Discovery by chosen intention (friendship, business, mentorship, travel, hobbies, social, couples friendship, romance where eligible); opt-in discoverability; mutual consent for private connections.', 'designed', 'Phase 7.', 516, true, false, false, false, false, false, null),
  ('social-journey', 'Social Ecosystem', 'Journey for connection and travel', 'Paid members: connection preferences, circles, events, new interests, trip planning and itineraries, within existing allowances.', 'designed', 'Phase 7.', 517, true, false, false, false, false, false, null),
  ('social-owner-controls', 'Social Ecosystem', 'Owner controls and community analytics', 'Categories, member-created groups, recommendation rules, moderation, events and announcements, visibility, access, notification defaults, aggregate analytics, safety reports, growth.', 'designed', 'Phase 8.', 518, true, false, false, false, false, false, null),
  ('social-couples-connection', 'Social Ecosystem', 'Couples Connection Community', 'Discover couples by interests, lifestyle and goals (local, nationwide, international, opt-in only); couple-to-couple connections; follow and join couples communities; double dates and gatherings through Connection Moments and the couples calendar. Both partners 21+.', 'designed', 'Phase 5.', 519, true, false, false, false, false, false, null),
  ('couples-shared-profile', 'Social Ecosystem', 'Shared couple profile and gallery with mutual consent', 'Published only when both partners approve; each shared photo needs both partners; either partner can withdraw. Individual accounts, journals, Journey conversations, counseling records and assessments stay private.', 'designed', 'Phase 5.', 520, true, false, false, false, false, false, null),
  ('couples-communication', 'Social Ecosystem', 'Couple-to-couple communication', 'Shared conversations, group messages, community discussions and event invitations; both partners keep individual privacy rights.', 'designed', 'Phase 5.', 521, true, false, false, false, false, false, null),
  ('couples-circles', 'Social Ecosystem', 'Couples Connection Circles', 'Travel couples, newlyweds, entrepreneurial couples, empty nesters, couples over 50, date nights, marriage growth, local couples, Elite couples, shared adventures; member-created couples circles with moderation.', 'designed', 'Phase 5. Owner: Elite couples eligibility.', 522, true, false, false, false, false, false, 'owner'),
  ('couples-singles-separation', 'Social Ecosystem', 'Couples networking separate from singles matchmaking', 'Couples friendship networking is never shown in singles matchmaking; partnered members never appear in singles discovery.', 'designed', 'Phase 5.', 523, true, false, false, false, false, false, null),
  ('social-couples-travel', 'Social Ecosystem', 'Couples Travel Exchange', 'Trip posts, destination questions, hotel/restaurant/excursion recommendations, reviews, travel photos and videos, voluntary itineraries, same-destination discovery (opt-in), trip invitations, private trip conversations, calendar coordination. Exact dates and locations never published automatically. No booking integrations without owner approval.', 'designed', 'Phase 6.', 524, true, false, false, false, false, false, 'owner')
insert into public.qa_features (key, department, title, tracker_key, href, purpose, steps, expected, sort) values
  ('social-profiles-photos', 'security', 'Profiles and photo privacy', 'social-profiles-photos', '/app', 'Photos follow their visibility settings at the storage level.', array['Upload photos with different visibility.', 'As another member, try to open a private photo link directly.']::text[], 'Private photos can''t be opened by others, even with the link; location data is removed.', 1300),
  ('social-connections', 'security', 'Connections and intentions', 'social-connections-graph', '/app', 'Mutual consent and intentions are respected.', array['Send a friendship request; confirm no romance is implied.', 'Decline and block; confirm no further contact.']::text[], 'Private connections only after acceptance; friendship never shown as romance.', 1310),
  ('social-feed', 'account', 'Connection Feed', 'social-feed', '/app', 'Posting, audiences and healthy feed controls.', array['Post a thought and a photo to one circle only.', 'Check who can see it; Appreciate, Discuss, Save; report a post.']::text[], 'Audience respected; no outrage ranking; reporting works.', 1320),
  ('calendar-create-share', 'account', 'Create and share events', 'calendar-events', '/app', 'Member-organized and shared external events are clearly labeled.', array['Create an original event and share an external event with its official link.', 'Check the labels and the time zone.']::text[], 'Labels are clear; no payment collection; details complete.', 1330),
  ('calendar-rsvp', 'account', 'Event interactions and calendars', 'calendar-interactions', '/app', 'Interested, attending, attend-with, reminders and calendars.', array['Mark Interested, then Attending; choose Looking for someone to attend with.', 'Add to your couples calendar; turn on a reminder.']::text[], 'Attendance shown only with consent; calendar and reminder work.', 1340),
  ('calendar-discovery-filters', 'account', 'Event discovery and filters', 'calendar-discovery', '/app', 'Local, national, international and virtual discovery.', array['Filter by city, date, category, price and eligibility.', 'As a free member, check only eligible events appear.']::text[], 'Accurate filters; eligibility respected.', 1350),
  ('calendar-safety', 'security', 'Event safety and fraud prevention', 'calendar-safety', '/admin', 'Reporting, verification and fraud signals.', array['Report an event; review it as owner.', 'Try to add a payment request in an event description.']::text[], 'Moderation queue receives it; payment requests are flagged.', 1360),
  ('circles-discover-join', 'account', 'Find Your Circle', 'social-circles', '/app', 'Recommend, never restrict.', array['Open Find Your Circle; read why each circle is recommended.', 'Join a circle outside your recommendations.']::text[], 'Reasons shown; any eligible circle can be joined.', 1370),
  ('circles-member-created', 'admin', 'Member-created circles', 'social-circles-member-created', '/admin', 'Owner approval and host moderation.', array['Propose a circle as an eligible member.', 'Approve it as owner; moderate a post as host.']::text[], 'Approval queue and host tools work.', 1380),
  ('connection-preferences', 'security', 'Connection preferences and privacy', 'connection-intelligence', '/app', 'Members control what recommendations use.', array['Open My connection preferences; correct and pause an input.', 'Confirm private assessment answers are never shown to others.']::text[], 'Preferences editable; confidential data never exposed or used to rank.', 1390),
  ('find-people', 'singles', 'Find People Like Me', 'find-people-like-me', '/app', 'Discovery by intention with consent.', array['Search for travel companions; then for business mentorship.', 'As a partnered member, confirm romance discovery isn''t offered.']::text[], 'Only opted-in members; romance only for eligible singles.', 1400),
  ('couples-shared-profile', 'couples', 'Shared couple profile with mutual consent', 'couples-shared-profile', '/app', 'Nothing shared publishes without both partners.', array['Partner A creates the couple profile and a photo.', 'Confirm it stays hidden until Partner B approves; then withdraw consent.']::text[], 'Both approvals required; withdrawal hides shared content.', 1410),
  ('couples-discover-connect', 'couples', 'Discover and connect with couples', 'social-couples-connection', '/app', 'Opt-in couple discovery and connections.', array['Search couples by interests and location.', 'Connect, message as four, plan a double date.']::text[], 'Only opted-in couples; communication and Moments work.', 1420),
  ('couples-circles', 'couples', 'Couples Connection Circles', 'couples-circles', '/app', 'Couples circles and eligibility.', array['Join the travel couples and date nights circles.', 'As a single member, confirm couples circles aren''t joinable.']::text[], 'Couples circles for linked couples only.', 1430),
  ('couples-singles-separation', 'security', 'Couples separate from singles matchmaking', 'couples-singles-separation', '/app', 'No cross-over between couples networking and singles matching.', array['As a single member, search matchmaking.', 'Confirm no couples or partnered members appear.']::text[], 'Complete separation.', 1440),
  ('couples-travel', 'couples', 'Couples Travel Exchange', 'social-couples-travel', '/app', 'Trips, recommendations and privacy.', array['Post a trip with month only; ask for restaurant recommendations.', 'Find couples going to the same destination; invite them; open a trip conversation.', 'Confirm exact dates, address and live location are not shown.']::text[], 'Trip features work; no exact whereabouts published.', 1450),
  ('social-journey', 'journey', 'Journey for events, circles and trips', 'social-journey', '/app/journey', 'Paid members get personalized suggestions.', array['As a paid member, ask Journey to plan a trip and suggest events.', 'As a free member, confirm standard recommendations remain.']::text[], 'Helpful suggestions within allowances; free members keep standard recommendations.', 1460),
  ('social-owner-controls', 'admin', 'Owner community controls', 'social-owner-controls', '/admin', 'Owner manages categories, rules, safety and growth.', array['Change a recommendation rule; archive a circle; read the safety report.']::text[], 'Controls work; analytics aggregate only.', 1470)
